-- Emit the exact argv generated by the export core, one argument per line.
package.path="mpv/portable_config/script-modules/?.lua;"..package.path
local E=require "editingcore"
local ff,source,dest,quality,mode=arg[1],arg[2],arg[3],tonumber(arg[4]),arg[5]
local options={encoder="cpu",crf=quality}
local settings=E.preset("moderate")
local a
if mode=="probe" then a=E.probe_args(ff,source,settings,nil,"cpu",options)
else a=E.export_args(ff,source,dest,settings,nil,"cpu",options) end
for _,v in ipairs(a) do print(v) end
